import { dayFrac, monthTicks, stackRows, timelineBars } from "./lib/timeline.js";
import { shiftDay } from "./lib/pool.js";
import { escapeHtml, t } from "./i18n/i18n.js";

const ROW_PX = 30;
const LABEL_GAP_PX = 10;
const LATE_FRAC = 0.72;
const BAR_MIN_PX = 10;
