content.content:
  text-align: center;
}

/* --- the year ------------------------------------------------------------ */

/* The strip across the top: twelve months, a bar per festival edition. Every
   position is logical, so a right-to-left page runs the year from the right. */
.timeline {
  margin: 14px 0 4px;
  padding: 36px 12px 8px;
  border: 1px solid var(--line);
  border-radius: 14px;
  /* Translucent, so the city behind the top of the page (23.17) shows
     through the year it is part of. */
  background: color-mix(in srgb, var(--paper) 78%, transparent);
  box-shadow: var(--shadow-soft);
}
.tl-year {
  position: relative;
}
.tl-months {
  position: relative;
  height: 18px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 8px;
}
/* The reader's own public holidays: a green orb on the months for each break
   they make, sized for the eye rather than the strip's scale, so it may sit
   over a month's name. */
.tl-orb {
  position: absolute;
  top: 3px;
  height: 11px;
  padding: 0;
  border: 1.5px solid var(--paper);
  border-radius: 999px;
  background: radial-gradient(circle at 35% 35%, var(--orb-shine), var(--orb) 70%);
  box-shadow: 0 1px 2px color-mix(in srgb, var(--ink) 25%, transparent);
  cursor: help;
  z-index: 2;
}
.tl-orb:hover,
.tl-orb:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--orb) 45%, transparent);
  outline-offset: 1px;
}
:root {
  --orb: light-dark(#2f9e57, #4cc27a);
  --orb-shine: light-dark(#8fdcaa, #a6f0c2);
}

/* The card a festival or an orb shows when pointed at. */
.tl-card {
  position: absolute;
  z-index: 5;
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-width: 320px;
  padding: 8px 11px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper);
  box-shadow: var(--shadow-soft);
  font-size: 0.78rem;
  color: var(--ink);
  pointer-events: none;
}
.tl-card[hidden] {
  display: none;
}
.tl-card-title {
  font-size: 0.85rem;
  font-weight: 800;
}
.tl-card-line.is-muted {
  color: var(--muted);
}
.tl-card-line.is-good {
  color: var(--ok-text, #047857);
  font-weight: 700;
}

.tl-month {
  position: absolute;
  top: 0;
  padding-inline-start: 4px;
  border-inline-start: 1px solid var(--line);
  font-size: 0.72rem;
  line-height: 18px;
  color: var(--muted);
  white-space: nowrap;
}
.tl-month--first {
  border-inline-start: 0;
  padding-inline-start: 0;
}
.tl-track {
  position: relative;
  min-height: 36px;
}
.tl-period {
  position: absolute;
  top: -8px;
  bottom: 0;
  background: color-mix(in srgb, var(--violet) 14%, transparent);
  border-radius: 4px;
}
/* Today: a stick figure standing on the months' line, holding up a sign. It
   shifts about a little, and cheers when the reader makes a choice. */
.tl-today {
    animation: none;
  }
}
.tl-item {
  position: absolute;
  display: flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  color: var(--ink);
  cursor: pointer;
  white-space: nowrap;
}
.tl-item--late {
  flex-direction: row-reverse;
}
.tl-bar {
  flex: 0 0 auto;
  height: 12px;
  border-radius: 6px;
  background: var(--muted);
}
.tl-item.is-empty .tl-bar {
  background: transparent;
  border: 2px solid var(--muted);
}
.tl-label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--muted);
}
.tl-item:hover .tl-label,
.tl-item:focus-visible .tl-label {
  color: var(--ink);
}
.tl-item.is-focus .tl-bar {
  background: var(--violet);
  border-color: var(--violet);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--violet) 28%, transparent);
}
.tl-item.is-focus .tl-label {
  color: var(--violet-dark);
  font-weight: 800;
}
.tl-none {
  margin: 4px 0;
  font-size: 0.85rem;
  color: var(--muted);
}

/* --- the trip: its band on the year, its dates, the flights either side ---- */

/* Each end of the trip's band is a handle: a line across the whole strip,
   months and all, with a grip at its middle to take hold of. */
.tl-handle {
  position: absolute;
  top: -26px;
  bottom: 0;
  width: 16px;
  margin-inline-start: -8px;
  cursor: ew-resize;
  touch-action: none;
  z-index: 2;
}
.tl-handle::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 2px;
  margin-left: -1px;
  background: var(--violet);
}
/* The planner's own grip (plan.css's .win-edge pill, upright here): two white
   bars on a violet capsule, running along the line it grabs. */
.tl-grip {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 12px;
  height: 26px;
  transform: translate(-50%, -50%);
  border-radius: 7px;
  background-color: var(--violet);
  background-image: linear-gradient(#fff, #fff), linear-gradient(#fff, #fff);
  background-repeat: no-repeat;
  background-size: 1.5px 12px;
  background-position: 4px center, 7.5px center;
  box-shadow: 0 1px 4px rgba(16, 24, 40, 0.3);
  transition: transform 0.12s ease;
}
.tl-handle:hover .tl-grip,
.tl-handle:focus-visible .tl-grip {
  transform: translate(-50%, -50%) scale(1.12);
}
.tl-handle:focus-visible {
  outline: none;
}
.tl-handle:focus-visible .tl-grip {
  outline: 3px solid color-mix(in srgb, var(--violet) 45%, transparent);
  outline-offset: 1px;
}
/* The trip's length, above the band, over the months. */
.tl-length {
  position: absolute;
  top: -46px;
  transform: translateX(-50%);
  padding: 0 6px;
  border-radius: 8px;
  background: var(--paper);
  font-size: 0.72rem;
  font-weight: 800;
  line-height: 16px;
  color: var(--violet-dark);
  white-space: nowrap;
  z-index: 3;
}
[dir="rtl"] .tl-length {
  transform: translateX(50%);
}

/* The dates between the two flight blocks: out on the left of the reader's
   line, home on the right, whichever way the line runs. */
.trip-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: stretch;
  gap: 10px;
