  outline: 3px solid color-mix(in srgb, var(--violet) 45%, transparent);
  outline-offset: 1px;
}
/* The trip's length, above the band, over the months. */
.tl-length {
  position: absolute;
  top: -46px;
  transform: translateX(-50%);
  padding: 0 6px;
  border-radius: 8px;
  background: var(--paper);
  font-size: 0.72rem;
  font-weight: 800;
  line-height: 16px;
  color: var(--violet-dark);
  white-space: nowrap;
  z-index: 3;
}
[dir="rtl"] .tl-length {
  transform: translateX(50%);
}
/* Each end's day of the month, at the top of its line: the first day's to the
   line's start side, the last day's to its end side, so a short trip's two
   never meet. */
.tl-day {
  position: absolute;
  top: -30px;
  padding: 0 3px;
  border-radius: 6px;
  background: var(--paper);
  font-size: 0.68rem;
  font-weight: 800;
  line-height: 14px;
  color: var(--violet-dark);
  z-index: 3;
  pointer-events: none;
}
.tl-day--from {
  transform: translateX(calc(-100% - 3px));
}
.tl-day--to {
  transform: translateX(3px);
}
[dir="rtl"] .tl-day--from {
  transform: translateX(calc(100% + 3px));
}
[dir="rtl"] .tl-day--to {
  transform: translateX(-3px);
}
/* The band itself is taken hold of to move the whole trip. */
.tl-track.is-grab,
.tl-track.is-grab .tl-item {
  cursor: grab;
}
.tl-track.is-dragging,
.tl-track.is-dragging .tl-item {
  cursor: grabbing;
}

/* The dates between the two flight blocks: out on the left of the reader's
   line, home on the right, whichever way the line runs. */
.trip-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: stretch;
  gap: 10px;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
}
.trip-row:empty {
  display: none;
}
.trip-dates {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 10px;
  min-width: 0;
}
.trip-date {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--muted);
}
.trip-date-input {
  font: inherit;
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--ink);
  padding: 4px 6px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper);
}
.trip-length {
  padding-bottom: 7px;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--violet-dark);
  white-space: nowrap;
}
.flight {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--violet) 5%, var(--paper));
  font-size: 0.85rem;
  min-width: 0;
}
.flight--empty {
  visibility: hidden;
}
.flight-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0 6px;
  min-width: 0;
}
.flight-plane {
  flex: 0 0 auto;
  color: var(--violet);
}
/* Taking off on the way out, coming home the other way. The plane points
   along the reader's line, so a right-to-left page turns it round too. */
.flight--out .way-fly {
  transform: rotate(45deg);
}
.flight--back .way-fly {
  transform: rotate(135deg);
}
[dir="rtl"] .flight--out .way-fly {
  transform: rotate(-45deg);
}
[dir="rtl"] .flight--back .way-fly {
  transform: rotate(-135deg);
}
[dir="rtl"] .flight .way-drive {
  transform: scaleX(-1);
}
/* Not yet said: dashed and quiet, the whole block a button, its picture
   turning between the ways of getting here. */
.flight--unsettled {
  border-style: dashed;
  border-color: color-mix(in srgb, var(--violet) 45%, var(--line));
  background: var(--paper);
  cursor: pointer;
}
.flight--unsettled:hover {
  background: color-mix(in srgb, var(--violet) 7%, var(--paper));
}
.arrive-icons {
  position: relative;
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  color: var(--violet);
  opacity: 0.7;
}
.arrive-icons > svg {
  position: absolute;
  inset: 0;
  opacity: 0;
  animation: arrive-turn 6s ease-in-out infinite;
}
.arrive-icons > svg:first-child {
  opacity: 1;
}
.arrive-icons > .way-train {
  animation-delay: -4s;
}
.arrive-icons > .way-drive {
  animation-delay: -2s;
}
@keyframes arrive-turn {
  0%, 28% { opacity: 1; }
  33%, 95% { opacity: 0; }
  100% { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .arrive-icons > svg {
    animation: none;
  }
}
.flight-title {
  font-weight: 800;
}
.flight-day {
  color: var(--muted);
  font-size: 0.78rem;
  white-space: nowrap;
}
.flight-note {
  margin: 0;
  color: var(--muted);
  font-size: 0.82rem;
}

