const fs=require('fs'),zlib=require('zlib');
const {encode}=require('/home/claude/EdFringeNow/product/requirements/shared/png.js');
const [,,file,out]=process.argv; const b=fs.readFileSync(file);
let p=8, ihdr, frames=[], cur=null;
while(p<b.length){const len=b.readUInt32BE(p),type=b.toString('ascii',p+4,p+8),d=b.subarray(p+8,p+8+len);p+=12+len;
 if(type==='IHDR')ihdr=d; else if(type==='fcTL'){cur={w:d.readUInt32BE(4),h:d.readUInt32BE(8),x:d.readUInt32BE(12),y:d.readUInt32BE(16),data:[]};frames.push(cur);}
 else if(type==='IDAT'&&cur)cur.data.push(d); else if(type==='fdAT')cur.data.push(d.subarray(4));}
frames.forEach((f,i)=>{const raw=zlib.inflateSync(Buffer.concat(f.data));const bpp=4,stride=f.w*bpp;const rgba=Buffer.alloc(f.w*f.h*4);let prev=Buffer.alloc(stride);
 for(let y=0;y<f.h;y++){const ft=raw[y*(stride+1)],line=raw.subarray(y*(stride+1)+1,(y+1)*(stride+1)),o=Buffer.alloc(stride);
  for(let x=0;x<stride;x++){const a=x>=bpp?o[x-bpp]:0,up=prev[x],c=x>=bpp?prev[x-bpp]:0;let v=line[x];
   if(ft===1)v+=a;else if(ft===2)v+=up;else if(ft===3)v+=(a+up)>>1;else if(ft===4){const pp=a+up-c,pa=Math.abs(pp-a),pb=Math.abs(pp-up),pc=Math.abs(pp-c);v+=(pa<=pb&&pa<=pc)?a:(pb<=pc?up:c);}o[x]=v&255;}
  o.copy(rgba,y*stride);prev=o;}
 fs.writeFileSync(`${out}_${i}.png`,encode({width:f.w,height:f.h,rgba}));console.log(i,f.w,f.h,f.x,f.y);});
EOF
